exercises.solution:
const encomendas = [
  { cliente: 'Rita', quantidade: 12 },
  { cliente: 'Davi', quantidade: 5 },
  { cliente: 'Luna', quantidade: 10 },
];

function encomendasGrandes(lista) {
  return lista.filter((encomenda) => encomenda.quantidade >= 10);
}

function totalDeUnidades(lista) {
  return lista.reduce((total, encomenda) => total + encomenda.quantidade, 0);
}

test('ficam as encomendas de 10 ou mais', () => {
  expect(encomendasGrandes(encomendas)).toEqual([
    { cliente: 'Rita', quantidade: 12 },
    { cliente: 'Luna', quantidade: 10 },
  ]);
});

test('sem encomenda grande: a lista vazia', () => {
  expect(encomendasGrandes([{ cliente: 'Davi', quantidade: 5 }])).toEqual([]);
});

test('as unidades somam 27', () => {
  expect(totalDeUnidades(encomendas)).toBe(27);
});

